contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= depositAmount);
        uint256 beforeBalance = address(c).balance;
        c.depositsCount(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;
        assert(afterBalance == 0 && address(this).balance >= beforeBalance);
    }

    receive() external payable {}
}

